"""
scripts/testing_part2.py
Second batch of fresher Testing interview questions.
"""

testing_part2_items = [
    ('What does `toBeCloseTo()` test in Jest and when must it be used?', '`toBeCloseTo()` compares floating-point numbers for approximate equality within a specified decimal precision (default 2 digits), avoiding floating point precision errors like `0.1 + 0.2 !== 0.3`.', 'Easy', 'Practical', 'expect(0.1 + 0.2).toBeCloseTo(0.3);', 'Why does `expect(0.1 + 0.2).toBe(0.3)` fail in JavaScript?'),
    ('What does `toHaveLength()` test in Jest?', '`toHaveLength(number)` asserts that an array, string, or object with a `.length` property has the specified length.', 'Easy', 'Practical', "expect([1, 2, 3]).toHaveLength(3);\nexpect('hello').toHaveLength(5);", 'Can `toHaveLength` be used on custom objects with a length property?'),
    ('What does `toHaveProperty()` test in Jest?', "`toHaveProperty(keyPath, value?)` checks if an object contains a specified property (including nested paths like `'user.address.city'`) and optionally validates its value.", 'Easy', 'Practical', "const user = { profile: { name: 'Alice' } };\nexpect(user).toHaveProperty('profile.name', 'Alice');", 'How do you check property existence without validating its value?'),
    ('What does `toBeInstanceOf()` test in Jest?', '`toBeInstanceOf(Class)` checks whether an object was instantiated using a specific constructor or class via the `instanceof` operator.', 'Easy', 'Practical', 'class CustomError extends Error {}\nexpect(new CustomError()).toBeInstanceOf(Error);', 'Why is this useful when testing custom error classes?'),
    ('What is `expect.stringMatching()` in Jest?', 'An asymmetric matcher that matches any string containing or matching a given regular expression, useful inside `toEqual` or `toHaveBeenCalledWith`.', 'Intermediate', 'Practical', 'expect(res.body).toEqual({\n  id: 1,\n  email: expect.stringMatching(/@example\\.com$/)\n});', 'What is `expect.stringContaining()`?'),
    ('What is `expect.any(Constructor)` in Jest?', 'An asymmetric matcher that matches any value created by the specified constructor (e.g. `expect.any(Number)`, `expect.any(String)`, `expect.any(Function)`).', 'Easy', 'Practical', 'expect(response).toEqual({\n  id: expect.any(Number),\n  createdAt: expect.any(Date)\n});', 'Why is `expect.any()` useful for autogenerated IDs and timestamps?'),
    ('What is `expect.not` modifier in Jest?', 'Chaining `.not` inverts any matcher: `expect(val).not.toBeNull()`, `expect(mockFn).not.toHaveBeenCalled()`.', 'Easy', 'Practical', 'expect(status).not.toBe(500);', 'Can `.not` be combined with custom matchers?'),
    ('How do you mock `window.localStorage` in Jest tests?', 'Define custom getter/methods using `Object.defineProperty` on `window.localStorage` or replace it with a mock storage object in setup files.', 'Intermediate', 'Practical', "const localStorageMock = (() => {\n  let store = {};\n  return {\n    getItem: jest.fn(key => store[key] || null),\n    setItem: jest.fn((key, value) => { store[key] = String(value); }),\n    clear: jest.fn(() => { store = {}; })\n  };\n})();\nObject.defineProperty(window, 'localStorage', { value: localStorageMock });", 'Why is mocking localStorage necessary in jsdom?'),
    ('How do you mock `window.matchMedia` in Jest?', "jsdom does not implement `matchMedia`. Mock it using `Object.defineProperty(window, 'matchMedia', { value: jest.fn().mockImplementation(query => ({ matches: false, addEventListener: jest.fn(), removeEventListener: jest.fn() })) })`.", 'Intermediate', 'Practical', "Object.defineProperty(window, 'matchMedia', {\n  writable: true,\n  value: jest.fn().mockImplementation(query => ({\n    matches: false,\n    media: query,\n    onchange: null,\n    addListener: jest.fn(),\n    removeListener: jest.fn()\n  }))\n});", 'What React libraries commonly break if matchMedia is unmocked (e.g. Ant Design, responsive hooks)?'),
    ('How do you mock `IntersectionObserver` in Jest?', 'Assign a mock class to `global.IntersectionObserver` in `setupTests.js` implementing `observe()`, `unobserve()`, and `disconnect()` as `jest.fn()`.', 'Intermediate', 'Practical', 'global.IntersectionObserver = class {\n  constructor(callback) { this.callback = callback; }\n  observe = jest.fn();\n  unobserve = jest.fn();\n  disconnect = jest.fn();\n};', 'What feature commonly uses IntersectionObserver (e.g. infinite scrolling, lazy loading)?'),
    ('What is `setupFilesAfterEnv` in `jest.config.js`?', 'An array of file paths that run code immediately after the test environment is installed and before each test file executes, commonly used to import `@testing-library/jest-dom` and configure global mocks.', 'Easy', 'Concept', "// jest.config.js\nsetupFilesAfterEnv: ['<rootDir>/src/setupTests.js']", 'How does it differ from `setupFiles`?'),
    ('What is `testEnvironment` in `jest.config.js` and what are its common options?', "Specifies the testing environment: `'jsdom'` (simulated browser environment with window/document for React/Vue) or `'node'` (standard Node.js runtime for backend Express/APIs).", 'Easy', 'Concept', "// For backend\ntestEnvironment: 'node'\n// For frontend\ntestEnvironment: 'jsdom'", "Why is `'node'` faster than `'jsdom'` for backend API tests?"),
    ('How do you increase the default test timeout in Jest?', "Use `jest.setTimeout(10000)` in code, pass `--testTimeout=10000` via CLI, or specify a third argument in `test('name', fn, 10000)`.", 'Easy', 'Practical', 'jest.setTimeout(15000);', 'What is the default timeout in Jest (5000ms)?'),
    ("What causes the Jest error 'Cannot log after tests are done'?", 'An asynchronous operation (like an un-awaited Promise, un-cleared timer, or unclosed database connection) continued executing and logging to the console after the test completed.', 'Intermediate', 'Debugging', '', 'How do you identify unclosed handles in Jest (`--detectOpenHandles`)?'),
    ('What does `npx jest --detectOpenHandles` do?', 'It prints stack traces of open resources (like active network sockets, unclosed database connections, active timers) that prevent Jest from exiting cleanly.', 'Intermediate', 'Practical', 'npx jest --detectOpenHandles --forceExit', 'Why is relying on `--forceExit` discouraged as a permanent solution?'),
    ('How do you test clicking a button with user-event in RTL?', "Set up user: `const user = userEvent.setup()`, render component, find button with `screen.getByRole('button', { name: /save/i })`, and `await user.click(button)`.", 'Easy', 'Practical', "const user = userEvent.setup();\nrender(<Button onClick={handleClick}>Save</Button>);\nawait user.click(screen.getByRole('button', { name: /save/i }));\nexpect(handleClick).toHaveBeenCalledTimes(1);", 'Why use a case-insensitive regex `/save/i`?'),
    ('How do you test typing text into a form input with user-event in RTL?', "Use `await user.type(screen.getByLabelText(/username/i), 'john_doe')`. It dispatches realistic keydown, keypress, and keyup events for each character.", 'Easy', 'Practical', "const user = userEvent.setup();\nrender(<LoginForm />);\nconst input = screen.getByLabelText(/email/i);\nawait user.type(input, 'test@example.com');\nexpect(input).toHaveValue('test@example.com');", "What matcher verifies the input's current value?"),
    ('How do you test selecting an option from a `<select>` dropdown in RTL?', "Use `await user.selectOptions(screen.getByRole('combobox'), 'blue')` or select by option text.", 'Easy', 'Practical', "const user = userEvent.setup();\nrender(<ColorPicker />);\nawait user.selectOptions(screen.getByRole('combobox'), 'green');\nexpect(screen.getByRole('option', { name: 'Green' }).selected).toBe(true);", "What is the ARIA role for a standard HTML `<select>` element ('combobox')?"),
    ('How do you test checking and unchecking a checkbox in RTL?', "Find the checkbox with `screen.getByRole('checkbox', { name: /agree/i })` and call `await user.click(checkbox)`. Assert with `expect(checkbox).toBeChecked()`.", 'Easy', 'Practical', "const user = userEvent.setup();\nrender(<TermsCheckbox />);\nconst cb = screen.getByRole('checkbox', { name: /agree to terms/i });\nexpect(cb).not.toBeChecked();\nawait user.click(cb);\nexpect(cb).toBeChecked();", 'What matcher verifies checked status?'),
    ('How do you test uploading a file in RTL?', "Use `await user.upload(input, file)` with a `new File(['content'], 'test.png', { type: 'image/png' })`.", 'Intermediate', 'Practical', "const user = userEvent.setup();\nrender(<FileUpload />);\nconst file = new File(['hello'], 'hello.png', { type: 'image/png' });\nconst input = screen.getByLabelText(/upload photo/i);\nawait user.upload(input, file);\nexpect(input.files[0]).toBe(file);\nexpect(input.files).toHaveLength(1);", 'Does `user.upload` support multiple files?'),
    ('How do you test keyboard navigation (e.g. Tab, Enter, Escape) in RTL?', "Use `await user.keyboard('{Tab}')`, `await user.keyboard('{Enter}')`, or `await user.keyboard('{Escape}')`.", 'Intermediate', 'Practical', "const user = userEvent.setup();\nrender(<Modal isOpen={true} />);\nawait user.keyboard('{Escape}');\nexpect(handleClose).toHaveBeenCalled();", 'Why is testing keyboard navigation critical for web accessibility?'),
    ('What does `screen.debug()` do in React Testing Library?', 'It prints the current formatted DOM HTML of the entire document (or a specific element: `screen.debug(element)`) to the console, helping developers inspect the rendered output during test failures.', 'Easy', 'Practical', "screen.debug();\nscreen.debug(screen.getByRole('navigation'));", 'Why should `screen.debug()` calls be removed before committing?'),
    ('How do you test waiting for an element to disappear from the DOM in RTL?', 'Use `await waitForElementToBeRemoved(() => screen.queryByText(/loading/i))`.', 'Intermediate', 'Practical', "render(<UserProfile />);\nawait waitForElementToBeRemoved(() => screen.queryByText(/loading/i));\nexpect(screen.getByText('John Doe')).toBeInTheDocument();", 'Why is `queryBy*` passed to `waitForElementToBeRemoved` instead of `getBy*`?'),
    ("What is the difference between `screen.getByRole('button')` and `screen.getByText('Click me')`?", '`getByRole` tests the semantic accessibility tree and element role, ensuring the element is genuinely a button and accessible to assistive tech. `getByText` only matches text content, even if rendered inside a non-semantic `div`.', 'Easy', 'Comparison', '', 'Why is `getByRole` preferred over `getByText` for interactive elements?'),
    ('How do you find an element by its accessible name when multiple buttons exist on screen?', "Pass the `{ name: /pattern/i }` option to `getByRole`: `screen.getByRole('button', { name: /submit/i })`.", 'Easy', 'Practical', "screen.getByRole('button', { name: /save changes/i });\nscreen.getByRole('button', { name: /cancel/i });", "What constitutes the 'accessible name' of a button?"),
    ('How do you test that an alert or notification appears on screen in RTL?', "Use `await screen.findByRole('alert')` or `screen.getByRole('alert')`.", 'Easy', 'Practical', "const alert = await screen.findByRole('alert');\nexpect(alert).toHaveTextContent('Password successfully reset');", "What HTML attribute confers role='alert' automatically in modern HTML?"),
    ('What is `cleanup()` in React Testing Library and do you need to call it manually in `afterEach()`?', '`cleanup()` unmounts rendered React component trees and cleans up the jsdom document. In Jest, RTL automatically configures `afterEach(cleanup)` so you almost never need to call it manually.', 'Easy', 'Concept', '', 'When would manual cleanup be required?'),
    ('How do you test sending a JSON body in a POST request with Supertest?', "Chain `.send({ key: 'value' })` on the request: `request(app).post('/api/users').send({ username: 'alice' }).expect(201)`.", 'Easy', 'Practical', "const res = await request(app)\n  .post('/api/products')\n  .send({ name: 'Book', price: 15 })\n  .expect(201);\nexpect(res.body.data.name).toBe('Book');", 'What header does `.send()` set automatically?'),
    ('How do you test uploading multipart/form-data files with Supertest?', "Use `.attach('fieldName', 'path/to/file.png')` on the request: `request(app).post('/api/upload').attach('avatar', 'test.jpg')`.", 'Intermediate', 'Practical', "const res = await request(app)\n  .post('/api/avatar')\n  .attach('avatar', 'tests/fixtures/sample.png')\n  .expect(200);", 'Can you send additional form fields alongside `.attach()` using `.field()`?'),
    ('How do you test sending query parameters with Supertest?', "Use `.query({ page: 2, limit: 10 })` or include them in the URL: `request(app).get('/api/users').query({ page: 2 })`.", 'Easy', 'Practical', "const res = await request(app)\n  .get('/api/search')\n  .query({ q: 'react', sort: 'desc' })\n  .expect(200);", 'How does Supertest encode query strings?'),
    ('How do you test cookies in Supertest requests?', "Pass a `Cookie` header string: `.set('Cookie', ['token=jwt_value_here'])`.", 'Intermediate', 'Practical', "const res = await request(app)\n  .get('/api/protected')\n  .set('Cookie', ['session_id=abc123xyz'])\n  .expect(200);", 'How do you inspect cookies sent by the server in response?'),
    ('How do you inspect cookies sent in a response with Supertest?', "Inspect the `res.headers['set-cookie']` array.", 'Intermediate', 'Practical', "const res = await request(app).post('/api/login').send(creds);\nexpect(res.headers['set-cookie']).toBeDefined();", 'What attribute ensures cookies cannot be accessed via JavaScript?'),
    ('How do you test custom Express error handling middleware?', 'Trigger an error condition (e.g. invalid payload or missing resource) and verify that the middleware catches the error, sets the correct status code (e.g. 400 or 500), and returns structured error JSON.', 'Intermediate', 'Practical', "const res = await request(app)\n  .post('/api/users')\n  .send({ invalid: true })\n  .expect(400);\nexpect(res.body.error).toBe('Validation Failed');", 'What is the 4-argument signature of Express error middleware?'),
    ('Why is it bad practice to test APIs against a shared live production or staging database?', 'Tests can corrupt or delete live user data, tests are not repeatable, concurrent test runs will conflict, and external network/database downtime will cause tests to fail falsely.', 'Easy', 'Best Practice', '', 'What should be used instead (e.g. in-memory test database, Docker container)?'),
    ('What is Newman?', 'Newman is the command-line collection runner for Postman that allows running and automating Postman test collections directly in terminal or CI/CD pipelines.', 'Easy', 'Concept', 'newman run postman_collection.json -e environment.json', 'How does Newman integrate with GitHub Actions?'),
    ('Which HTTP status code should be verified when a requested item ID does not exist in the database?', '404 Not Found.', 'Easy', 'MCQ', '', {'A': '400 Bad Request', 'B': '404 Not Found', 'C': '500 Internal Server Error', 'D': '204 No Content'}, 'B', 'When would 400 Bad Request be returned instead of 404?'),
    ('Which HTTP status code should be verified when a request succeeds but has no content to return (e.g. DELETE)?', '204 No Content.', 'Easy', 'MCQ', '', {'A': '200 OK', 'B': '201 Created', 'C': '204 No Content', 'D': '202 Accepted'}, 'C', 'Does a 204 No Content response contain a response body?'),
    ('How do you locate an element by its accessible role in Playwright?', "Use `page.getByRole(role, { name: 'Text' })` (e.g. `page.getByRole('button', { name: 'Sign in' })`).", 'Easy', 'Practical', "await page.getByRole('button', { name: 'Submit' }).click();", 'Why are role locators preferred in Playwright over CSS selectors?'),
    ('How do you fill an input field in Playwright?', "Use `await page.getByLabel('Username').fill('myuser')`.", 'Easy', 'Practical', "await page.getByLabel('Email').fill('user@example.com');\nawait page.getByLabel('Password').fill('secret123');", 'How does `fill()` differ from `type()` or `pressSequentially()`?'),
    ('What is the difference between `fill()` and `pressSequentially()` in Playwright?', '`fill()` directly sets the input value in a single operation after clearing. `pressSequentially()` simulates physical keystroke-by-keystroke typing, firing keyboard events for each letter.', 'Intermediate', 'Comparison', '', 'When is `pressSequentially()` necessary?'),
    ('How do you assert that a URL changed after navigation in Playwright?', "Use `await expect(page).toHaveURL('https://example.com/dashboard')` or regex: `await expect(page).toHaveURL(/.*dashboard/)`.", 'Easy', 'Practical', 'await expect(page).toHaveURL(/.*\\/dashboard/);', 'Does `expect(page).toHaveURL()` automatically wait for navigation?'),
    ('How do you assert that an element is visible in Playwright?', 'Use `await expect(locator).toBeVisible()`.', 'Easy', 'Practical', "await expect(page.getByText('Welcome back')).toBeVisible();", 'How do you assert that an element is hidden or not attached?'),
    ('How do you intercept and mock API requests in Playwright?', "Use `page.route(url, handler)`: `await page.route('**/api/users', route => route.fulfill({ status: 200, json: [{ id: 1, name: 'Alice' }] }))`.", 'Intermediate', 'Practical', "await page.route('**/api/profile', async route => {\n  await route.fulfill({\n    status: 200,\n    contentType: 'application/json',\n    body: JSON.stringify({ name: 'Mock User' })\n  });\n});", 'Why is network interception in Playwright faster than spinning up a real backend for UI tests?'),
    ('How do you test handling a browser `alert` or `confirm` dialog in Playwright?', "Listen for the `'dialog'` event: `page.on('dialog', dialog => dialog.accept())` before clicking the button that triggers it.", 'Intermediate', 'Practical', "page.on('dialog', async dialog => {\n  expect(dialog.message()).toBe('Are you sure?');\n  await dialog.accept();\n});\nawait page.getByRole('button', { name: 'Delete' }).click();", 'What does `dialog.dismiss()` simulate?'),
    ('How do you emulate a mobile device viewport in Playwright?', "Configure `devices['iPhone 13']` in `playwright.config.ts` or set viewport size dynamically: `await page.setViewportSize({ width: 375, height: 667 })`.", 'Easy', 'Practical', 'await page.setViewportSize({ width: 375, height: 667 });', 'What other device parameters does Playwright emulate (e.g. touch, userAgent)?'),
    ('How do you take a screenshot of a specific element in Playwright?', "Call `.screenshot({ path: 'button.png' })` directly on the locator: `await page.getByRole('button').screenshot({ path: 'btn.png' })`.", 'Easy', 'Practical', "await page.locator('#chart').screenshot({ path: 'chart.png' });", 'How do you capture a full-page scrolling screenshot?'),
    ('How do you capture a full page screenshot in Playwright?', "Pass `{ fullPage: true }`: `await page.screenshot({ path: 'page.png', fullPage: true })`.", 'Easy', 'Practical', "await page.screenshot({ path: 'screenshot.png', fullPage: true });", 'Where are screenshots saved if relative path is given?'),
]
